// Function to check if b is a predecessor of a
bool isPred(const string &a, const string &b) {
    if (a.size() != b.size() + 1) {
        return false;
    }
    int i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] == b[j]) {
            i++;
            j++;
        } else {
            i++;
        }
    }
    return (j == b.size());
}

