int longestStringChain(vector<string> &words) {

    // Sort words based on length
    sort(words.begin(), words.end(), [](const string &a, 
                                        const string &b) {
        return a.size() < b.size();
    });

    int n = words.size();
    vector<int> dp(n, 1);
    int res = 1;

    // Iterate over each word
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (isPred(words[i], words[j])) {
                dp[i] = max(dp[i], dp[j] + 1);
            }
        }
        res = max(res, dp[i]);
    }
